import{_ as s,o as a,c as i,a3 as t}from"./chunks/framework.MGD2uYU7.js";const r=JSON.parse('{"title":"SC-08 — Hướng dẫn / Hỏi đáp","description":"","frontmatter":{"title":"SC-08 — Hướng dẫn / Hỏi đáp"},"headers":[],"relativePath":"wireframes/public/sc-08-hoi-dap.md","filePath":"wireframes/public/sc-08-hoi-dap.md","lastUpdated":1791606799000}'),c={name:"wireframes/public/sc-08-hoi-dap.md"};function l(p,n,d,h,e,o){return a(),i("div",null,[...n[0]||(n[0]=[t('<h1 id="sc-08-—-huong-dan-hoi-đap" tabindex="-1">SC-08 — Hướng dẫn / Hỏi đáp <a class="header-anchor" href="#sc-08-—-huong-dan-hoi-đap" aria-label="Permalink to &quot;SC-08 — Hướng dẫn / Hỏi đáp&quot;">​</a></h1><p><span class="wf-badge muted">ĐỘ PHỨC TẠP: THẤP — TRANG NỘI DUNG TĨNH</span> <span class="wf-badge info">Route: /hoi-dap</span> <span class="wf-badge muted">Nguồn: docs/05 §3 SC-08 · docs/05 §8 · docs/08 BR-AU/BR-VW/BR-KYC</span></p><p><strong>Ai xem màn này</strong>: Guest mới biết sàn (đọc điều kiện mua NOXH trước khi đăng ký), người sắp đấu giá (đọc quy chế + giải thích cọc), CS (gửi link từng mục cho khách qua hotline 1900-xxx). <strong>Mục đích / cảm xúc thiết kế</strong>: trang <strong>pháp lý dễ đọc</strong> — đây là nơi đặt copy pháp lý (điều kiện, quy chế, tiền cọc). Không trang trí, không CTA chèn ngang; mục lục rõ, anchor link deep-link được từng câu hỏi. <strong>Ví dụ số dùng trong bản vẽ</strong>: cọc 5% khởi điểm (min 10.000.000 ₫) · notice ≥ 7 ngày · đóng đăng ký trước giờ mở 24h · bước giá 1–20% · anti-snipe +60 giây · thanh toán trúng giá 24h · hoàn cọc thua 3 ngày làm việc · phí đấu giá 1,5%.</p><h2 id="_1-desktop-—-toc-sidebar-trai-noi-dung-phai" tabindex="-1">1. Desktop — TOC sidebar trái + nội dung phải <a class="header-anchor" href="#_1-desktop-—-toc-sidebar-trai-noi-dung-phai" aria-label="Permalink to &quot;1. Desktop — TOC sidebar trái + nội dung phải&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/hoi-dap#quy-che-dau-gia</span></div><div class="wf-body"><div class="wf-header"><span class="wf-logo">AnPhuc</span><span class="wf-nav"><span>Mua nhà</span><span>Đấu giá</span><span>Bảng gói</span><span class="active">Hướng dẫn</span></span><span class="wf-header-actions"><span class="wf-btn sm">Đăng nhập</span><span class="wf-btn sm primary">Đăng bán</span></span></div><div class="wf-container"><span class="wf-title xl">Hướng dẫn &amp; Hỏi đáp <span class="wf-callout">1</span></span><div class="wf-row" style="align-items:flex-start;margin-top:14px;"><div class="wf-sidebar wf-sticky-note"><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">TRONG TRANG NÀY</span><span class="wf-text wf-accent">1. Điều kiện mua nhà ở xã hội</span><span class="wf-text">2. Mua nhà qua sàn như thế nào?</span><span class="wf-text">3. Quy chế đấu giá <span class="wf-callout">2</span></span><span class="wf-text">4. Tiền cọc — hỏi &amp; đáp</span><span class="wf-text">5. Đặt lịch xem nhà</span><span class="wf-text">6. An toàn &amp; bảo mật</span><div class="wf-note" style="margin-top:10px;">Không tìm thấy câu trả lời? Gọi CSKH <b>1900-xxx</b> (08:00–20:00)</div></div></div><div class="wf-grow wf-col" style="gap:14px;"><div class="wf-card flat" id="dieu-kien"><div class="pad wf-col" style="gap:8px;"><span class="wf-title lg">1. Điều kiện mua nhà ở xã hội</span><span class="wf-text">Nội dung tóm tắt điều kiện theo quy định NOXH hiện hành (đối tượng, điều kiện nhà ở, thu nhập…) — <b>copy final do Ops + Pháp chế viết</b>, wireframe chỉ giữ khung.</span><div class="wf-lines"><span class="w-100"></span><span class="w-90"></span><span class="w-100"></span><span class="w-75"></span></div><div class="wf-note">⚖ Mục pháp lý — nội dung do Ops soạn, Pháp chế duyệt trước khi lên production (blocking MS2, docs/05 §8). Design không tự viết số/điều khoản. <span class="wf-callout">3</span></div></div></div><div class="wf-card flat" id="quy-che"><div class="pad wf-col" style="gap:10px;"><span class="wf-title lg">3. Quy chế đấu giá — dòng thời gian một phiên</span><div class="wf-steps"><div class="wf-step done">Công bố<br><b>≥ 7 ngày</b> trước mở</div><div class="wf-step done">Đăng ký + cọc<br>đóng <b>trước mở 24h</b></div><div class="wf-step active">Phiên mở<br>tối đa 24 giờ</div><div class="wf-step">Kết thúc<br>+60s yên lặng</div><div class="wf-step">Thanh toán<br><b>24 giờ</b></div></div><table class="wf-table"><tbody><tr><td>Giá khởi điểm · bước giá</td><td>Hiện trên card phiên (SC-05) · bước giá 1–20% khởi điểm, <b>cố định sau công bố</b></td></tr><tr><td>Tiền cọc tham gia</td><td>5% giá khởi điểm, tối thiểu 10.000.000 ₫ — phải về tài khoản sàn trước hạn đăng ký</td></tr><tr><td>Phút cuối có giá mới</td><td>Phiên tự cộng thêm 60 giây, không giới hạn số lần (chống &quot;đè giây cuối&quot;)</td></tr><tr><td>Người trúng</td><td>Trả giá cao nhất khi hết giờ; thanh toán trong 24 giờ: giá trúng + phí 1,5% − cọc đã nộp</td></tr><tr><td>Người không trúng</td><td>Hoàn cọc 100% trong 3 ngày làm việc, tự động — không cần thao tác</td></tr><tr><td>Bỏ cọc / quá hạn thanh toán</td><td>Mất cọc + tạm ngưng quyền đấu giá cho tới khi ADMIN mở lại</td></tr><tr><td>Danh tính người tham gia</td><td>Ẩn danh tuyệt đối — chỉ hiện bí danh TV-XXXX trong phiên</td></tr></tbody></table><span class="wf-small">Mọi con số trên trace về docs/08: BR-AU-03/04/06/09/12/13/14/15/16/20 — khi BR đổi, trang này đổi theo. <span class="wf-callout">4</span></span></div></div><div class="wf-card flat" id="coc"><div class="pad wf-col" style="gap:8px;"><span class="wf-title lg">4. Tiền cọc — hỏi &amp; đáp <span class="wf-callout">5</span></span><div class="wf-card flat"><div class="pad wf-row between middle"><span class="wf-text"><b>Cọc bao nhiêu và nộp thế nào?</b></span><span class="wf-strong">−</span></div><div class="pad" style="border-top:1px solid var(--wf-line);padding-top:10px;"><span class="wf-text">5% giá khởi điểm (ví dụ: khởi điểm 1.800.000.000 ₫ → cọc 90.000.000 ₫). Nộp qua VNPay hoặc chuyển khoản thủ công với nội dung bill đúng mã `ANPHUC pay_…` — chuyển khoản thủ công được ADMIN xác nhận trong 2 giờ làm việc.</span></div></div><div class="wf-card flat"><div class="pad wf-row between middle"><span class="wf-text"><b>Không trúng thì bao lâu tiền cọc về?</b></span><span class="wf-strong">+</span></div></div><div class="wf-card flat"><div class="pad wf-row between middle"><span class="wf-text"><b>Phiên bị hủy thì cọc của tôi ra sao?</b></span><span class="wf-strong">+</span></div></div><div class="wf-card flat"><div class="pad wf-row between middle"><span class="wf-text"><b>Trúng giá mà không đủ tiền trong 24 giờ?</b></span><span class="wf-strong">+</span></div></div></div></div><div class="wf-card flat" id="lich-xem"><div class="pad wf-col" style="gap:6px;"><span class="wf-title lg">5. Đặt lịch xem nhà</span><span class="wf-text">· Cần tài khoản đã xác minh CCCD (duyệt trong 48 giờ).</span><span class="wf-text">· Chọn lịch trước 24h và trong 14 ngày (08:00–20:00) — giờ GMT+7.</span><span class="wf-text">· Tối đa 3 lịch chờ — hủy lịch cũ để đặt mới.</span><span class="wf-text">· Chủ nhà phản hồi trong 24 giờ; quá giờ hẹn 2 tiếng lịch tự hết hiệu lực.</span></div></div></div></div></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/05 §3 SC-08 · docs/08)</div><ol><li><span class="num">1</span><span>Trang tĩnh thuần — không gọi API nghiệp vụ; nội dung quản lý như content (v1: hardcode i18n constants theo NFR-C-01; CMS là ngoài scope). Mỗi mục có <b>anchor id</b> (`#dieu-kien`, `#quy-che`, `#coc`…) để CSKH deep-link từng phần khi trả lời khách. <span class="ref">docs/05 §2</span> <span class="ref">NFR-C-01</span></span></li><li><span class="num">2</span><span>TOC sticky trái, highlight mục đang đọc (scroll-spy); footer link &quot;Quy chế đấu giá&quot; trỏ thẳng `#quy-che` — là link pháp lý bắt buộc ở mọi trang (SC-06 modal quy chế cũng tham chiếu mục này). <span class="ref">docs/05 §2</span></span></li><li><span class="num">3</span><span><b>Copy pháp lý = Ops + Pháp chế duyệt, blocking MS2</b> (docs/05 §8): điều kiện mua NOXH, quy chế, FAQ cọc. Wireframe/Figma chỉ chốt khung + độ dài; dev không hardcode text tự nghĩ — placeholder trong constants chờ nội dung final. <span class="ref">docs/05 §8</span></span></li><li><span class="num">4</span><span>Mọi con số trong bảng quy chế phải khớp docs/08: notice ≥7 ngày (BR-AU-03), đóng đăng ký start−24h (BR-AU-04), cọc 5% min 10tr (BR-AU-06), bước giá 1–20% bất biến sau publish (BR-AU-09), anti-snipe +60s không giới hạn (BR-AU-12), kết thúc cần 60s yên lặng (BR-AU-13), phí 1,5% + hạn 24h (BR-AU-14/15), forfeit + suspend (BR-AU-15/16), pseudonym (BR-AU-20). <b>Đổi BR → đổi trang này trong cùng PR.</b> <span class="ref">docs/08 §12</span></span></li><li><span class="num">5</span><span>Accordion Q/A: 1 câu mở sẵn/mục, toggle +/−; chỉ 1 câu mở trong cùng khối. Câu trả lời dùng đúng copy hệ thống ở chỗ có message chuẩn (VD khung giờ đặt lịch = message VIEWING_SLOT_INVALID docs/06 §5). <span class="ref">docs/06 §5</span> <span class="ref">BR-VW-01/02</span></span></li><li><span class="num">6</span><span>Mục &quot;An toàn &amp; bảo mật&quot;: giải thích ẩn danh chủ nhà, dữ liệu CCCD mã hóa theo NĐ13, nguyên tắc không chuyển tiền ngoài nền tảng — khung do PM giữ, copy Pháp chế duyệt. Không có trạng thái Loading/Error (trang tĩnh) — chỉ cần offline fallback của FE framework. <span class="ref">NFR-S-05</span></span></li></ol></div><h2 id="_2-mobile-360px-—-toc-thu-thanh-muc-luc-đau-trang" tabindex="-1">2. Mobile 360px — TOC thu thành mục lục đầu trang <a class="header-anchor" href="#_2-mobile-360px-—-toc-thu-thanh-muc-luc-đau-trang" aria-label="Permalink to &quot;2. Mobile 360px — TOC thu thành mục lục đầu trang&quot;">​</a></h2><div class="wf"><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-btn sm">Đăng nhập</span></div><div class="wf-container" style="padding:12px;"><span class="wf-title lg">Hướng dẫn &amp; Hỏi đáp</span><div class="wf-card flat" style="margin-top:10px;"><div class="pad wf-col" style="gap:4px;"><span class="wf-small wf-strong">TRONG TRANG NÀY</span><span class="wf-text wf-accent">1. Điều kiện mua NOXH</span><span class="wf-text">2. Mua nhà qua sàn</span><span class="wf-text">3. Quy chế đấu giá</span><span class="wf-text">4. Tiền cọc — hỏi &amp; đáp</span><span class="wf-text">5. Đặt lịch xem nhà</span><span class="wf-text">6. An toàn &amp; bảo mật</span></div></div><div class="wf-card flat" style="margin-top:12px;"><div class="pad wf-col" style="gap:6px;"><span class="wf-title">3. Quy chế đấu giá</span><div class="wf-steps"><div class="wf-step done">Công bố<br>≥7 ngày</div><div class="wf-step done">Cọc<br>−24h</div><div class="wf-step active">Phiên mở</div><div class="wf-step">24h trả tiền</div></div><table class="wf-table"><tbody><tr><td>Cọc</td><td>5%, tối thiểu 10.000.000 ₫</td></tr><tr><td>Phút cuối</td><td>+60 giây mỗi giá mới</td></tr><tr><td>Thua</td><td>hoàn cọc 3 ngày làm việc</td></tr></tbody></table></div></div><div class="wf-card flat" style="margin-top:12px;"><div class="pad wf-col" style="gap:6px;"><span class="wf-title">4. Tiền cọc — hỏi &amp; đáp</span><div class="wf-row between middle"><span class="wf-text"><b>Cọc bao nhiêu, nộp thế nào?</b></span><span class="wf-strong">−</span></div><span class="wf-small">5% khởi điểm (VD 1.800.000.000 ₫ → cọc 90.000.000 ₫) · VNPay hoặc chuyển khoản nội dung `ANPHUC pay_…` · manual xác nhận ≤2h làm việc.</span><div class="wf-row between middle" style="border-top:1px dashed var(--wf-line);padding-top:6px;"><span class="wf-text"><b>Không trúng, bao lâu về?</b></span><span class="wf-strong">+</span></div><div class="wf-row between middle" style="border-top:1px dashed var(--wf-line);padding-top:6px;"><span class="wf-text"><b>Phiên bị hủy?</b></span><span class="wf-strong">+</span></div></div></div><div class="wf-note">CSKH 1900-xxx (08:00–20:00)</div></div><div class="wf-footer"><span>AnPhucRealEstate — vận hành bởi An Phuc</span><span>Quy chế đấu giá</span></div></div></div><div class="wf-legend"><div class="t">Chú thích mobile</div><ol><li><span class="num">M</span><span>TOC sticky → card &quot;Trong trang này&quot; đầu trang (tap = scroll tới anchor, vẫn giữ deep-link `#quy-che`). Steps timeline rút còn 4 mốc trên mobile; bảng quy chế hiển thị đủ — <b>không cắt bớt điều khoản nào</b> vì lý do màn hẹp (table cuộn ngang nếu cần). Hotline luôn ở cuối trang, gọi được bằng 1 tap.</span></li></ol></div><h2 id="_3-checklist-designer-khi-dung-figma-cho-sc-08" tabindex="-1">3. Checklist designer khi dựng Figma cho SC-08 <a class="header-anchor" href="#_3-checklist-designer-khi-dung-figma-cho-sc-08" aria-label="Permalink to &quot;3. Checklist designer khi dựng Figma cho SC-08&quot;">​</a></h2><ul><li>[ ] Đủ layout: desktop (TOC sticky 220px + nội dung) / tablet 768 (TOC gập lên đầu) / mobile 360 (card mục lục + accordion)</li><li>[ ] 6 mục nội dung có anchor riêng, TOC highlight scroll-spy; footer &quot;Quy chế đấu giá&quot; trỏ <code>#quy-che</code></li><li>[ ] Khung timeline 5 bước của phiên đấu giá (steps component dùng lại SC-21/24 nếu có)</li><li>[ ] Bảng quy chế đủ 7 dòng con số (notice/đăng ký/cọc/bước giá/anti-snipe/thanh toán/hoàn cọc) — số khớp docs/08, không tự chế</li><li>[ ] Accordion Q/A: 2 trạng thái +/−, 1 câu mở sẵn, copy placeholder đánh dấu &quot;chờ Pháp chế&quot;</li><li>[ ] Đánh dấu rõ trong Figma khu vực nào là <b>copy pháp lý blocking MS2</b> (note vàng) để không ai điền text tự nghĩ</li><li>[ ] Ngày/giờ trong ví dụ: <code>dd/MM/yyyy HH:mm</code> + GMT+7; tiền <code>90.000.000 ₫</code></li><li>[ ] Không emoji icon trong UI production (⚖ là placeholder vị trí)</li><li>[ ] Accessibility: heading hierarchy đúng (h1 trang → h2 mục → h3 câu hỏi); accordion dùng button thật + aria-expanded; TOC là nav có aria-label; contrast AA</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ (con số quy chế, điều kiện NOXH) cần PM duyệt trên docs/08 và Pháp chế duyệt copy trước.</p></div>',12)])])}const u=s(c,[["render",l]]);export{r as __pageData,u as default};
